// #79f484 (045c8f36802b8c7e6179f484) AC2 — в журнале доступа (/admin/access-log) удаление «מחיקה בניקוי 90 יום»
// приписано запустившему (ручная чистка — Super Admin) или «מערכת…» (автоматическая), а не «משתמש לא ידוע».
// spec: specs/access-log.md (раздел 5) · seed: tests/seed.admin.spec.ts.
// Только чтение: сама «ניקוי 90 יום» НЕ запускается (необратимое удаление). Проверяются записи с 04.11.2026
// (фикс d7bf266); старые строки до фикса — история (решение пользователя 04.11), не проверяются.
// Факт 04.11.2026 16:21 (testim): «הפעלת ניקוי 90 יום על רשומה» и «מחיקה בניקוי 90 יום» — «מנהל מערכת · מנהל/ת מערכת».
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const FIRST_DAY = '2026-11-04';
const PURGE_DELETE = 'מחיקה בניקוי 90 יום';
const UNKNOWN = 'משתמש לא ידוע';

type LogResponse = { entries: unknown[]; limit?: number };
type Row = { day: string; user: string; action: string };

const iso = (d: Date) => d.toLocaleDateString('en-CA');
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);

async function filterDay(page: Page, day: string): Promise<LogResponse> {
  await page.locator('#access-log-from').fill(day);
  await page.locator('#access-log-to').fill(day);
  const res = page.waitForResponse((r) => r.url().includes('/rpc/admin_list_access_log') && r.request().method() === 'POST');
  await page.getByRole('button', { name: 'סינון', exact: true }).click();
  const r = await res;
  expect(r.ok(), `admin_list_access_log ${day}`).toBeTruthy();
  return (await r.json()) as LogResponse;
}

/** Ячейки «משתמש» и «פעולה» каждой строки таблицы. */
async function rows(page: Page, day: string): Promise<Row[]> {
  const cells = await page.evaluate(() => {
    const t = document.querySelector('main table');
    if (!t) return [];
    const heads = [...t.querySelectorAll('thead th')].map((h) => (h as HTMLElement).innerText.trim());
    const ui = heads.indexOf('משתמש');
    const ai = heads.indexOf('פעולה');
    if (ui < 0 || ai < 0) throw new Error('нет колонок «משתמש»/«פעולה»: ' + heads.join('|'));
    return [...t.querySelectorAll('tbody tr')].map((r) => ({
      user: ((r.children[ui] as HTMLElement)?.innerText || '').trim(),
      action: ((r.children[ai] as HTMLElement)?.innerText || '').trim(),
    }));
  });
  return cells.map((c) => ({ ...c, day }));
}

test.describe('Журнал доступа — исполнитель удаления «ניקוי 90 יום» (#79f484 · #045c8f36802b8c7e6179f484)', () => {
  test('admin: строки «מחיקה בניקוי 90 יום» с 04.11.2026 подписаны исполнителем, не «משתמש לא ידוע» @desktop @prod-safe #79f484 #045c8f36802b8c7e6179f484', async ({ asUser }) => {
    test.setTimeout(180_000);
    const page = await asUser('admin');
    await page.goto('/admin/access-log');
    await expect(page.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible();

    const purgeRows: Row[] = [];
    for (let d = new Date(FIRST_DAY + 'T00:00:00'); d <= new Date(); d = addDays(d, 1)) {
      const day = iso(d);
      const data = await filterDay(page, day);
      if (!data.entries.length) continue;
      if (data.entries.length >= (data.limit ?? 200)) {
        test.info().annotations.push({ type: 'warning', description: `${day}: лимит ответа — проверены только последние ${data.entries.length}` });
      }
      await expect(page.locator('main table tbody tr')).toHaveCount(data.entries.length);
      purgeRows.push(...(await rows(page, day)).filter((r) => r.action === PURGE_DELETE));
    }

    test.info().annotations.push({ type: 'checked', description: `${purgeRows.length} строк «${PURGE_DELETE}»: ${purgeRows.map((r) => `${r.day} ${r.user}`).join('; ')}` });
    // Журнал неизменяем: ручная чистка 04.11 16:21 (QA-C7-2110-D3) в нём есть.
    expect(purgeRows.length, `строк «${PURGE_DELETE}» с ${FIRST_DAY}`).toBeGreaterThan(0);
    // «מה רצוי» 2: «המחיקה ביומן הגישה מיוחסת למי שהפעיל אותה (או ל"מערכת" במחיקה אוטומטית), לא ל"משתמש לא ידוע"».
    for (const r of purgeRows) {
      expect.soft(r.user, `${r.day}: исполнитель удаления`).not.toContain(UNKNOWN);
      expect.soft(r.user, `${r.day}: исполнитель удаления пуст`).not.toMatch(/^(—|-|)$/);
    }
    // Ручная чистка 04.11 — Super Admin.
    expect(purgeRows.filter((r) => r.day === FIRST_DAY).some((r) => r.user.includes('מנהל מערכת'))).toBe(true);
  });
});
